data comments_analysis;
set raw_data.fraud;
drop rownames;
*To avoid words with common roots being double counted, we take the maximum of the counts of these words;
fraud_A=max(fraud1, fraud2, fraud11, fraud12, fraud13, fraud14, fraud15);
fraud_B=max(fraud3, fraud4, fraud5, fraud6, fraud29, fraud30);
fraud_C=sum(max(fraud7, fraud8, fraud9), fraud10);
fraud_D=sum(max(fraud16, fraud17, fraud18), fraud19);
fraud_E=fraud20;
fraud_F=fraud21;
fraud_G=sum(fraud22, fraud23, fraud24, fraud25);
fraud_H=max(fraud26, fraud27, fraud28);
fraud_I=sum(fraud31, fraud32, fraud33);
fraud_J=sum(max(fraud34, fraud35, fraud36), max(fraud37, fraud38));
fraud_K=sum(max(fraud39, fraud40, fraud41), fraud42);
fraud_L=sum(max(fraud43, fraud44), fraud45, fraud46);
fraud_M=sum(max(fraud47, fraud48, fraud49), fraud50);
fraud_N=max(fraud51, fraud52);
fraud=(100*sum(fraud_A, fraud_B, fraud_C, fraud_D, fraud_E, fraud_F, fraud_G, fraud_H, fraud_I, fraud_J, fraud_K, fraud_L, fraud_M, fraud_N));
run;

proc sql;
create table temp as select
a.*, b.fraud as fraud_pre
from temp a left join comments_analysis (where=(dummy_dates=1)) b
on (a.link=b.link);

set raw_data.city_state_nomatch_nomatch_d;
