%let path=[redacted-path-ca8b33fc9c24];

*Assign SAS libraries;
libname raw_data "&path.\raw_data";
libname fdic "&path.\raw_data\fdic";
libname fdic2 "&path.\raw_data\fdic2";
libname data "&path.\data";

%clean_kickstarter_data;
%merge_kickstarter_data;
%prepare_dataset;

/*** Consumer protection ***/

data alldata;
set alldata;
*Create the post variable;
post=0;
if beg_date>=mdy(9,20,2014) then post=1;
*Create the treated variable;
treated=0;
if location_state="AL" then treated=1;
if location_state="AK" then treated=8;

data cam;
set raw_data.cam;
*Convert number of backers to numeric;
backers_n=1*compress(backers,, 'kd');
*Standardize currency of amount pledged;
pledged_currency=compress(pledged, , "d");
pledged_currency=compress(pledged_currency, ',');
pledged_currency=compress(pledged_currency, '.');
if pledged_currency='$' then pledged_currency='USD';
if pledged_currency='-$' then pledged_currency='USD';
if pledged_currency='AU$' then pledged_currency='AUD';
if pledged_currency='CA$' then pledged_currency='CAD';
if pledged_currency='HK$' then pledged_currency='HKD';

/*** Cleaning community tab data ***/

data com;
set raw_data.com;
*Convert number of new and returning backers to numeric;
newbackers_n=1*compress(newbackers,",");
returningbackers_n=1*compress(returningbackers,",");
*New and returning backers are only available if the number of backers is greater than 10. We set new and returning backers equal to 0 if missing;
if returningbackers_n=. then returningbackers_n=0;
if newbackers_n=. then newbackers_n=0;
drop newbackers returningbackers;
run;

data data.com;
set com;
keep link newbackers_n returningbackers_n;
run;

/*** Cleaning comments tab data ***/

data cot;
set raw_data.cot;
*Convert number of comments and number and length of collaborator, creator, participants, and superbacker replies to numerical;
comments_n=1*compress(comments,",");
collaboratorreplies_n=1*collaboratorreplies;
collaboratorreplies_length=1*collaboratorRepliesLength;
creatorreplies_n=1*creatorreplies;
creatorreplies_length=1*CreatorRepliesLength;
participantsreplies_n=1*participantsreplies;
participantsreplies_length=1*participantsRepliesLength;
superbackerreplies_n=1*superbackerreplies;
superbackerreplies_length=1*superbackerRepliesLength;
*If there are no collaborator, creator, participants, and superbacker replies, i.e., the number and length of collaborator, creator, participants, and superbacker replies is missing, we set it equal to zero;
if collaboratorreplies_n=. then collaboratorreplies_n=0;
if collaboratorreplies_length=. then collaboratorreplies_length=0;
if creatorreplies_n=. then creatorreplies_n=0;
if creatorreplies_length=. then creatorreplies_length=0;
if participantsreplies_length=. then participantsreplies_length=0;
if superbackerreplies_length=. then superbackerreplies_length=0;
*Aggregate creator and collaborator replies;
creator_coll_rep_n=creatorreplies_n+collaboratorreplies_n;
creator_coll_rep_length=creatorreplies_length+collaboratorreplies_length;
drop rownames comments collaboratorreplies collaboratorRepliesLength creatorreplies CreatorRepliesLength participantsreplies participantsRepliesLength superbackerreplies superbackerRepliesLength;
run;

data data.cot;
set cot;
keep link collaboratorreplies_length collaboratorreplies_n comments_n creatorreplies_length creatorreplies_n participantsreplies_length participantsreplies_n superbackerreplies_length superbackerreplies_n creator_coll_rep_n creator_coll_rep_length;
run;

data cre;
set raw_data.cre;
*Extract creator country and creator state;
creatorlocation2=compress(creatorlocation,' ');
if length(scan(creatorlocation2,-1,','))>2 then creator_country=strip(scan(creatorlocation,-1,','));
if length(scan(creatorlocation2,-1,','))=2 then do; creator_state=scan(creatorlocation2,-1,','); creator_country='USA'; end;
drop creatorlocation2;

data data.cre;
set cre;
keep link creator_state creator_country foreign_creator facebook_n bio_length fullbio_length bio_length_combined projectsbacked_n lastlogin_date projectscreated_n author_cre creator_name;
run;

/*** Cleaning Updates tab data ***/

data upd;
set raw_data.upd;
*Extract project launched date;
launched_month=scan(launcheddate,1,' ');
launched_year=1*scan(launcheddate,-1,',');
launched_day=1*scan(scan(launcheddate,1,','),2,' ');
if launched_month='January' then nlaunched_month=1;
if launched_month='February' then nlaunched_month=2;
if launched_month='March' then nlaunched_month=3;
if launched_month='April' then nlaunched_month=4;
if launched_month='May' then nlaunched_month=5;
if launched_month='June' then nlaunched_month=6;
if launched_month='July' then nlaunched_month=7;
if launched_month='August' then nlaunched_month=8;
if launched_month='September' then nlaunched_month=9;
