set raw_data.gss7216_r1a;
*Extract trust and comphome variables from the GSS survey data;
keep id year region trust comphome;
run;

data gss_trust;
set gss (where=(trust in (1 2)));
*Create an indicator variable set equal to one if the respondent answers “Yes” to the question "Do you think most
people can be trusted?," and zero otherwise;
d_trust=0;
if trust=1 then d_trust=1;
run;

*Compute the percentage of “Yes” answers to the question “Do you think most people can be trusted?” in each region and year;
proc means data=gss_trust mean n noprint;
var d_trust;

set raw_data.gss7216_r1a;
*Extract courts variable from the GSS survey data;
keep id year region courts;
run;

data gss;
set gss;
if courts in (1 2 3) then d_courts_deal_criminal=0;
*Create an indicator variable equal to 1 if respondent answers "About right" to the question "In general, do you think the courts in this area deal too harshly or not harshly enough with criminals?";
if courts=3 then d_courts_deal_criminal=1;
run;

*Compute percentage of respondents that answer "About right" to the question "In general, do you think the courts in this area deal too harshly or not harshly enough with criminals?" in each region and year;
proc means data=gss mean n noprint;
var d_courts_deal_criminal;
class region year;
output out=courts mean(d_courts_deal_criminal)=md_courts_deal_criminal;
run;

