a.*, b.cbsa_metro, b.numemp
from fdic a left join fdic2 b
on (a.fed_rssd=b.fed_rssd) and (a.repdte=b.repdte);
quit;

data fdic;
set fdic;
small1=0; small2=0; small3=0;
if asset<50000 then small1=1;
if asset>=50000 and asset<100000 then small2=1;
if asset>=100000 and asset<500000 then small3=1;
assetsmall1=asset*small1;
assetsmall2=asset*small2;
assetsmall3=asset*small3;
assetsmall1_2=asset*max(small1,small2);
run;

proc means data=fdic noprint sum;
var asset assetsmall1 assetsmall2 assetsmall3 assetsmall1_2;
class stalp repdte;
output out=fractionassets sum(asset assetsmall1 assetsmall2 assetsmall3 assetsmall1_2)=sasset sassetsmall1 sassetsmall2 sassetsmall3 sassetsmall1_2;
run;

data fractionassets;
set fractionassets (where=(stalp ne '' and repdte ne .));
drop _freq_ _type_;
fraction_small1=sassetsmall1/sasset;
fraction_small2=sassetsmall2/sasset;
fraction_small3=sassetsmall3/sasset;
fraction_small1_2=sassetsmall1_2/sasset;
run;

data fdic;
set fdic;
capital_assets=rbct1j/asset;
share1=0; share2=0; share3=0; share4=0;
if capital_assets<0.02 then share1=1;
if capital_assets>=0.02  and capital_assets< 0.04 then share2=1;
if capital_assets>=0.04  and capital_assets< 0.06 then share3=1;
if capital_assets>=0.06  and capital_assets< 0.08 then share4=1;
assetshare1=asset*share1;
assetshare2=asset*share2;
assetshare3=asset*share3;
assetshare4=asset*share4;
run;

proc means data=fdic noprint sum;
var share1-share4 asset;
class stalp repdte;
output out=sharebanks sum(assetshare1-assetshare4 asset)=sassetshare1-sassetshare4 sasset;
run;

data sharebanks;
set sharebanks (where=(stalp ne '' and repdte ne .));
drop _freq_ _type_;
share1=sassetshare1/sasset;
share2=sassetshare2/sasset;
share3=sassetshare3/sasset;
share4=sassetshare4/sasset;
run;

proc means data=sharebanks;
